mapper.select:
SELECT A.BOOKSET_ID AS booksetId, A.BOOKSET_NAME AS booksetName, A.ACCT_MODE AS acctMode, A.BOOKSET_ID_TMPL AS booksetIdTmpl, B.BOOKSET_NAME AS booksetNameTmpl,
#{item} AS schemeType, nvl(D.SCH_ID, (select info.sch_id from BOK_SCHEME_INFO info where info.is_default = 'Y' and info.scheme_type = #{item} and rownum = 1)) AS schId, nvl(D.SCH_NAME, (select info.SCH_NAME from BOK_SCHEME_INFO info where info.is_default = 'Y' and info.scheme_type = #{item} and rownum = 1)) AS schName, C.BOOKSET_SCHEME_ID AS booksetSchemeId FROM BOK_BOOKSET A LEFT JOIN BOK_BOOKSET B ON B.BOOKSET_ID = A.BOOKSET_ID_TMPL LEFT JOIN BOK_BOOKSET_PLAN C ON C.BOOKSET_ID = A.BOOKSET_ID AND C.SCHEME_TYPE = #{item} LEFT JOIN BOK_SCHEME_INFO D ON D.SCH_ID = C.SCHEME_ID AND D.SCHEME_TYPE = C.SCHEME_TYPE WHERE A.BOOKSET_TYPE = #{booksetType}
AND A.BOOKSET_ID IN
#{item}
AND A.BOOKSET_NAME LIKE '%' || #{booksetName} || '%'
AND A.ACCT_MODE = #{acctMode}
AND D.SCH_ID = #{schId}
AND A.BOOKSET_ID_TMPL = #{booksetIdTmpl}
ORDER BY booksetId

SELECT distinct B.SCH_ID id, B.SCH_NAME text FROM BOK_BOOKSET_PLAN A INNER JOIN BOK_SCHEME_INFO B ON B.SCH_ID = A.SCHEME_ID INNER JOIN BOK_BOOKSET D ON D.BOOKSET_ID = A.BOOKSET_ID WHERE 1=1
AND D.BOOKSET_TYPE = #{booksetType}
AND D.BOOKSET_ID = #{booksetId}
AND B.SCHEME_TYPE IN
#{item}
AND B.SCH_NAME like '%' || #{likeStr} || '%' OR B.SCH_ID like '%' || #{likeStr} || '%'
order by B.SCH_ID desc
